template <typename T> struct Processor {
    static T execute(T val) { return val; } // Default behavior
};

template <>
struct Processor<int> {
    static int execute(int val) {
        return val * 2; // Specialized for integers
    }
};

template <>
struct Processor<double> {
    static double execute(double val) {
        return val + 10.0; // Specialized for doubles
    }
};

// Use: Processor<int>::execute(5);
// Use: Processor<double>::execute(5.0);
// Compile-time path resolution, zero virtual overhead.
